        Criterion(key: "genre_shift", ru: "смена жанра", en: "genre shift", hint: "starts as one genre, becomes another", group: "genre_mix"),
        Criterion(key: "unpredictable", ru: "непредсказуемость", en: "unpredictable", hint: "hard to guess what comes next", group: "twists"),
        Criterion(key: "rewatch_value", ru: "хочется пересмотреть", en: "rewatch value", hint: "rewards a second viewing", group: "twists"),
        Criterion(key: "social_commentary", ru: "об обществе", en: "social commentary", hint: "says something about society", group: "ideas"),
        Criterion(key: "existential", ru: "о смысле", en: "existential", hint: "questions about life and meaning", group: "ideas"),
    ]
    private static let byKey = Dictionary(uniqueKeysWithValues: all.map { ($0.key, $0) })
    static func criterion(_ key: String) -> Criterion? { byKey[key] }

    /// Слишком общие черты — в метки только если других нет.
    static let generic: Set<String> = ["haunting", "lingering"]

    /// Словарь для запроса: по группам, «ключ (что значит)».
    static func promptList() -> String {
        groups.map { g in "\(g.ru): " + all.filter { $0.group == g.key }.map { "\($0.key) (\($0.hint))" }.joined(separator: "; ") }
            .joined(separator: "\n")
    }

    /// Ключи → названия черт; незнакомые отбрасываются, не больше трёх.
    static func label(_ keys: [String], english: Bool) -> String {
        var seen = Set<String>()
        let found = keys.compactMap { key -> Criterion? in
            let k = key.trimmingCharacters(in: .whitespaces).lowercased()
            guard seen.insert(k).inserted else { return nil }
            return byKey[k]
        }.prefix(3)
        return found.enumerated().map { index, c in
            let text = english ? c.en : c.ru
            return index == 0 ? text.prefix(1).uppercased() + text.dropFirst() : text
        }.joined(separator: " · ")
    }
}
